INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1494008-ce315', 'stk-rami_ali_ce_1990', 'CE 315', 'info', '{"desc": "بداية الديزاين … مهمة جدااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااااا\n\nخذها معا الاسطى …\n\nاذا بتروح Design Office حتلقى نفس الشي اللي بتسويه بالكلاس بتسويه بالشركة على STAAD.Pro معا الكود الجميل حق ال ACI", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-315-reinforced-concrete-i/120675/4", "user": "Rami_Ali_CE_1990", "ts": 1528578013000, "tid": 120675, "pn": 4}}', 1528578013000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1503873-ce315', 'stk-user10533', 'CE 315', 'info', '{"desc": "المادة عن الاناليسس والديزاين …\nف البداية تصممون beam والمومنت والشير عليه كيف بيكون ثم تروحون للـ slab والـ column\nكيف ممكن تحط حديد داخل الخرسانة , مكانه وطول قطره , وكم عدده وبرضو كم طول ارتفاع السكشن والعرض تبعه\nكيف ممكن الـ beam يتحمل الاثقال اللي عليه وإيش أعلى قوة ممكن تحطها بدون يصير failure\nاللاب يعلمك على برنامج STAAD Pro للديزاين بتستفيد منه مررررررررة صدقني\nاخذتها مع الأسطى أفضل الدكاترة الللي يشرحونها … الاختبارات Open bock\n\nبيني وبينكم أحس إني يوم أخذتها صرت مهندس حقيقي وليس بالإسم :d", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-315-reinforced-concrete-i/120675/5", "user": "user10533", "ts": 1545348914000, "tid": 120675, "pn": 5}}', 1545348914000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce315', 'stk-civil_engineer1', 'CE 315', 'doc', '{"docs": [{"id": "stk-dr-f98575", "n": "Dr. Maher A. Bader", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فصل 112\nCE 315\nبنود التقييم :\n\nالتحضير : كل محاضرة يمرر ورقة التحضير\nطريقة الشرح : هذي اهم مادة في السيفيل الرجال ماخذها سهالات سواليف وصور و على الاغلب ما فيه شرح او شرح ماله فايدة\nالكويزات : كويزين اختيارات واكتب قوانين\nالمياجر: اوبن بوك ومستواها عادي جدا وما تقيس فهم الطالب\nالفاينلات : نفس الاختبارات\nالقريد النهائي:a\nالصوت:واضح\nإضافات : المواد المهمة لا تاخذها مع هالدكتور لان يمكن ما تطلع بقريد وتصير خسرت الفايدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1058158-ce315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-maher-a-bader/98575/9", "user": "civil_engineer1", "ts": 1340293257000, "tid": 98575, "pn": 9}}]}', 1340293257000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce315', 'stk-user2967', 'CE 315', 'doc', '{"docs": [{"id": "stk-dr-f98585", "n": "Dr. Abul Kalam Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 315 - 111\n\nالتحضير :\nالتحضير بالصوت ينادي عليك … ويمديك تحضر خويك لانه مايرفع راسه خير شر يشيك\n\nطريقة الشرح :\nعنده نوت خاص يصوره لك ويوزعه ع مدى ترم كامل … النوت قووي جدا وواضح\nوالشرح يكون ع السلايدات والسبوره\n\nالكويزات : لايوجد\n\nالمياجر والفاينلات :\nيقسمها الى قسمين … 50 % لكل قسم … قسم يكون فقط معك الكود … وقسم الاخر مفتووح (كتب وكود ونوت وهوم ووركس)\nالاسئلة منوعه منها السهل والوسط والصعب\n\nالقريد النهائي:\na+\n\nالصوت:\nواضح جدا وازين مافيه لكنة الهنود بالانجليزي خفيفه عنده>>> متعقد\n\nإضافات :\nبروجكت نهاية الترم يحتاج له جهد … تصميم ببرنامج الستاد برو وحل مانيول … بس افضل مالبروجكت يطلعك فاهم للكورس\n\nبداية الترم يتم تقسيمكم لقروبات من 3 اشخاص … ويكون الهوم ووركات والبروجكت تسلم من كل قروب\n\nالنهاية\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p969324-ce315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abul-kalam-azad/98585/2", "user": "user2967", "ts": 1326754628000, "tid": 98585, "pn": 2}}]}', 1326754628000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ayesh_abdu-ce315', 'stk-ayesh_abdu', 'CE 315', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\n\nانا درسني في الترم 132 مادة CE 315 Reinforced Concrete 1\nولكن كان النظام اللكتشر يدرسها البروفيسور MOHAMMAD BALUCH واللاب مقسوم الى قسمين الجزء الاول يدرسنا الدكتور Osta الجزء الي شرحه البروفيسور ثم يبدأ اللاب ف للاسف ما درسني ماده هو مسؤول عنها تماما\n\nولكن للأمانه لولا الله ثم انه كان يعيد شرح البروفيسور ولا كان ما فهمت ولا كلمة فالله يجزاه كل خير وكان يبذل مجهوود كبيير معنا وعنده استعداد يعيد المعلومه الف مره وباكثر من طريقه ليييين تفهم ومن شده احترامي له كنت ودي انزل معه Reinforced Concrete 2 وللاسف ما قدرت\n\nما كان يحضر في معظم الاحيان\n\nالمياجر كان الاسئلة الي يصححها ناخذ فيها قريب الدرجه الكامله ولمن يصحح البروفيسور سؤال يخسف فينا الارض صراحه ابداااع تصحييحه\n\nالقريد النهائي A+++++++++++++++++++ ولو فيه اعلى اعطيته على ابداعه\n\nصوته ممتاز وواضح جدا ويحكي انجليزي واذا حس القدامه ضاع يتكلم بالعربي وجدا خلوووق وكرييم ومحترم بتعامله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1395735-ce315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/6", "user": "ayesh_abdu", "ts": 1409556849000, "tid": 152669, "pn": 6}}]}', 1409556849000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_132-ce315', 'stk-_132', 'CE 315', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172\nكورس 305 Ce\nالتحضير يومي اول الكلاس ؛إذا حضرت متأخر يعطيك ليت . الشرح عن طريق نوتات هو كاتبها مستواها متوسط أما شرحه هو اعتبره متوسط . الهوموركات بشكل اسبوع وكل هوم ورك يبيله 6 صفحات إلى 7 (كثيرة مرة ) ، عطنا 4 كوزآت + 2 كوز تيك هوم حله ببرنامج StadPro (حق مادة ce 315 و ce 408 ) .\nبالنسبة للميجر :\nميجر 1 : الافرج حوالي 53 يعتير طايح ،لأن المتيريال صعبة\nميجر 2 : الافرج حوالي 71 لأن ميجر ون أفرج طايح فجاب ميجر 2 سهل .\nالفاينل : المتيريال متوسطة بس جاب لنا فاينل صعب ،وحط على 30% من الاختبار 13 سوال اختيارات وكل اختيار 4 فقرات ولازم توريه كيف حليت ؛ وإذا اخترت خيار خطأ راح يخصم عليك 1% من التوتل ، طبعا الفاينل ليس comprehensive.\nبشكل عام تقيمي للدكتور C إلى C+ .\nكورس CE 318\nالتحضير يومي اول الكلاس ؛إذا حضرت متأخر يعطيك ليت . الشرح عن طريق نوتات هو كاتبها مستواها فوق المتوسط إلا الجزئية اللي قبل الفاينل كانت النوتات مش واضحة مرة أما شرحه هو اعتبره متوسط . الهوموركات كل اسبوعين هوم ورك ،الكوزات عطانا 5 كوزآت.\nميجر 1: الافرج تقريبا 28 من أصل 40\nميجر 2 : الافرج تقريبا 34 من أصل 50\nالفاينل : 80% بالمية على المتيريال الأخيرة و 20 % على باقي المنهج ( جاب لنا عن solving constraints by graph ) ,بس كان الفاينل مستواه معقول .\n* فيه نقطة حاب اوضحها؛ اختبارنا الفاينل من ببداية اول اسبوع من الاختبارات النهائيه ؛والدكتور مارفع القريدات إلا بآخر يوم لل سبمشن قريد .\nبشكل عام تقيمي للدكتور B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492550-ce315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/4", "user": "_132", "ts": 1526522942000, "tid": 176818, "pn": 4}}]}', 1526522942000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
